function YeOldeInfos.IsGamepadUIActive()
	if IsInGamepadPreferredMode() then
		return true
	end
	-- Fallback for Accessibility Mode
	if GetSetting_Bool and SETTING_TYPE_ACCESSIBILITY and ACCESSIBILITY_SETTING_ACCESSIBILITY_MODE then
		return GetSetting_Bool(SETTING_TYPE_ACCESSIBILITY, ACCESSIBILITY_SETTING_ACCESSIBILITY_MODE)
	end
	return false
end

local function SetIconScale(value)
	YeOldeInfos.SV.IconScale = value
	for _, bar in pairs(YeOldeInfos.Bars) do
		bar:SetIconScale(value)
	end
end

local function SetFontSize(value)
	YeOldeInfos.SV.FontSize = value
	for _, bar in pairs(YeOldeInfos.Bars) do
		bar:SetFontSize(value)
	end
end

local function SetFontType(value)
	YeOldeInfos.SV.FontType = value
	for _, bar in pairs(YeOldeInfos.Bars) do
		bar:SetFontType(value)
	end
end

local function SetShowOptions()
	for _, bar in pairs(YeOldeInfos.Bars) do
		bar:RefreshVisibility()
	end
end

