function YeOldeInfos.Initialize(_, addOnName)
	if addOnName ~= YeOldeInfos.AddonName then
		return
	end
	YeOldeInfos.SV = ZO_SavedVars:NewAccountWide("YeOldeInfosVars", 1.0, nil, YeOldeInfos.Default, nil)

	YeOldeInfos.Bars = {}
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeSpeed:New("Speed")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeCrafting:New("Crafting")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeGolds:New("Golds")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldePlayerCurrencies:New("Currencies")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeAccountCurrencies:New("Account")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeMail:New("Mail")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeInventorySpace:New("Space")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeTime:New("Time")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldeTrain:New("Train")
	YeOldeInfos.Bars[#YeOldeInfos.Bars + 1] = YeOldePromoEvents:New("PromoEvents")

	YeOldeInfos.CreateSettingsMenu()

	local function PlayerActivated()
		for _, bar in ipairs(YeOldeInfos.Bars) do
			bar:Activate(bar:IsEnabled())
		end
	end

	EVENT_MANAGER:RegisterForEvent(YeOldeInfos.AddonName, EVENT_PLAYER_ACTIVATED, PlayerActivated)
	EVENT_MANAGER:UnregisterForEvent(YeOldeInfos.AddonName, EVENT_ADD_ON_LOADED)
end

EVENT_MANAGER:RegisterForEvent(YeOldeInfos.AddonName, EVENT_ADD_ON_LOADED, YeOldeInfos.Initialize)
